.bgle-hero{position:relative;z-index:2;padding:2px 170px 10px 28px}
@media(max-width:800px){.bgle-hero{padding-right:28px}}
.bgle-greet{display:flex;align-items:center;gap:9px;color:var(--text-muted);font-size:13px;margin-bottom:10px}
.bgle-h1{font-family:'Space Grotesk','Inter',sans-serif;font-size:clamp(20px,2.6vw,27px);
  margin:0 0 18px;letter-spacing:-.015em;font-weight:700;color:var(--heading-color)}
.bgle-h1 b{color:#f0a04b}
.bgle-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:12px;margin-bottom:18px}
.bgle-k{background:var(--card-bg);border:1px solid var(--border-color);border-radius:13px;padding:13px 15px}
[data-theme=dark] .bgle-k{background:linear-gradient(180deg,#1b1b21,#15151a);box-shadow:inset 0 1px 0 rgba(255,255,255,.05)}
.bgle-k .l{font-size:10.5px;text-transform:uppercase;letter-spacing:.08em;color:var(--text-muted);font-weight:700}
.bgle-k .v{font-family:'Space Grotesk',sans-serif;font-size:21px;font-weight:700;margin-top:4px;color:var(--heading-color)}
.bgle-door{display:inline-block;background:#f0a04b;color:#191203 !important;font-weight:800;text-decoration:none !important;
  padding:10px 22px;border-radius:11px;font-size:13.5px;margin-bottom:8px}
.bgle-rail{position:relative;z-index:2;display:grid;grid-template-columns:repeat(5,1fr);gap:11px;padding:14px 28px 24px}
@media(max-width:900px){.bgle-rail{grid-template-columns:1fr 1fr}.bgle-line{display:none}}
.bgle-line{position:absolute;left:38px;right:38px;top:50%;height:2px;z-index:0;border-radius:2px}
.bgle-line .spark{position:absolute;top:-3px;width:8px;height:8px;border-radius:50%;
  background:#f0a04b;box-shadow:0 0 12px 3px rgba(240,160,75,.7);
  animation:bglespark 3.5s linear infinite}
@keyframes bglespark{0%{left:0%}100%{left:100%}}
.bgle-stg{position:relative;z-index:2;background:var(--card-bg);border:1px solid var(--border-color);
  border-radius:14px;padding:13px 13px 11px;display:block;transition:transform .15s,border-color .15s}
[data-theme=dark] .bgle-stg{background:linear-gradient(180deg,#1b1b21,#15151a);box-shadow:inset 0 1px 0 rgba(255,255,255,.05)}
.bgle-stg:hover{transform:translateY(-3px);border-color:#f0a04b}
.bgle-stg .n{display:inline-grid;place-items:center;width:25px;height:25px;border-radius:50%;
  font-weight:800;font-size:12px;margin-bottom:8px}
.bgle-stg.done .n{background:rgba(47,181,111,.15);color:#2fb56f;border:1.5px solid #2fb56f}
.bgle-stg.now .n{background:#f0a04b;color:#191203;border:1.5px solid #f0a04b;width:29px;height:29px;box-shadow:0 0 14px rgba(240,160,75,.5)}
.bgle-stg.wait .n{background:transparent;color:var(--text-muted);border:1.5px solid var(--border-color)}
.bgle-stg b{display:block;font-family:'Space Grotesk','Inter',sans-serif;font-size:13px;line-height:1.3;color:var(--heading-color)}
.bgle-stg span{display:block;font-size:11px;color:var(--text-muted);margin-top:3px;line-height:1.4}
.bgle-stg.done b{color:#2fb56f}
.bgle-stg.now{border:2px solid #f0a04b;transform:scale(1.05);z-index:3;animation:bglebreathe 2.2s ease-in-out infinite}
.bgle-stg.now b{color:#f0a04b;font-size:14px}
.bgle-stg.now:hover{transform:scale(1.05) translateY(-3px)}
@keyframes bglebreathe{0%,100%{box-shadow:0 0 16px rgba(240,160,75,.18)}50%{box-shadow:0 0 30px rgba(240,160,75,.4)}}
.bgle-stg.now::after{content:"HAPPENING NOW";position:absolute;top:-9px;right:9px;font-size:8.5px;
  font-weight:800;letter-spacing:.12em;background:#f0a04b;color:#191203;padding:2px 8px;border-radius:100px}
.bgle-stg .st{position:absolute;top:11px;right:11px;font-size:10px;font-weight:800}
.bgle-stg.done .st{color:#2fb56f}.bgle-stg.now .st{color:#f0a04b}.bgle-stg.wait .st{color:var(--text-muted)}
.bgle-foot{position:relative;z-index:2;padding:0 28px 12px;font-size:10.5px;color:var(--text-muted)}
.bgle-greet svg{filter:drop-shadow(0 0 5px rgba(240,160,75,.8));animation:bgleglow 2.4s ease-in-out infinite;flex:none;vertical-align:-3px;margin-right:2px}
@keyframes bgleglow{0%,100%{filter:drop-shadow(0 0 3px rgba(240,160,75,.5))}50%{filter:drop-shadow(0 0 9px rgba(240,160,75,1))}}

.bgle-hub{position:relative;z-index:4;padding:0 28px 18px}
.bgle-hub-t{font-size:10.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--text-muted);font-weight:800;margin-bottom:8px}
.bgle-hub-search{position:relative;max-width:420px}
.bgle-hub-search input{width:100%;background:var(--card-bg);border:1px solid var(--border-color);
  border-radius:11px;padding:10px 15px;font-size:13.5px;color:var(--text-color)}
[data-theme=dark] .bgle-hub-search input{background:linear-gradient(180deg,#1b1b21,#15151a)}
.bgle-hub-search input:focus{outline:none;border-color:#f0a04b}
.bgle-hub-drop{position:absolute;top:calc(100%+4px);left:0;right:0;background:var(--card-bg);
  border:1px solid var(--border-color);border-radius:11px;z-index:50;display:none;overflow:hidden;
  box-shadow:0 10px 30px rgba(0,0,0,.25)}
.bgle-hub-drop div{padding:9px 14px;font-size:13px;cursor:pointer}
.bgle-hub-drop div:hover{background:rgba(240,160,75,.1);color:#f0a04b}
.bgle-hub-drop small{color:var(--text-muted);margin-left:7px}
.bgle-hub-card{margin-top:12px}
.bgle-hc{display:flex;gap:18px;flex-wrap:wrap;background:var(--card-bg);border:1px solid var(--border-color);
  border-radius:15px;padding:17px 19px}
[data-theme=dark] .bgle-hc{background:linear-gradient(180deg,#1b1b21,#15151a);box-shadow:inset 0 1px 0 rgba(255,255,255,.05)}
.bgle-hc .av{width:56px;height:56px;border-radius:50%;background:rgba(240,160,75,.15);color:#f0a04b;
  display:grid;place-items:center;font-family:'Space Grotesk',sans-serif;font-weight:700;font-size:19px;flex:none;
  border:1.5px solid rgba(240,160,75,.4);background-size:cover;background-position:center}
.bgle-hc .who b{font-family:'Space Grotesk',sans-serif;font-size:16px;color:var(--heading-color);display:block}
.bgle-hc .who span{font-size:12px;color:var(--text-muted)}
.bgle-hc .facts{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:10px 22px;flex:1;min-width:280px}
.bgle-hc .f .l{font-size:9.5px;text-transform:uppercase;letter-spacing:.08em;color:var(--text-muted);font-weight:700}
.bgle-hc .f .v{font-size:13.5px;font-weight:600;color:var(--heading-color);margin-top:1px}
.bgle-hc .acts{display:flex;gap:8px;flex-wrap:wrap;width:100%;margin-top:6px}
.bgle-hc .acts a{font-size:11.5px;font-weight:700;text-decoration:none !important;padding:6px 13px;
  border-radius:100px;border:1px solid var(--border-color);color:var(--text-color) !important}
.bgle-hc .acts a:hover{border-color:#f0a04b;color:#f0a04b !important}
.bgle-hc .acts a.pri{background:#f0a04b;color:#191203 !important;border-color:#f0a04b}

script:
(function(root){
  root = root_element || document.getElementById('bgle-root');
  if(!root) return;
  var MONTHS=['January','February','March','April','May','June','July','August','September','October','November','December'];
  var now=new Date(), ym=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0');
  root.querySelector('.bgle-month .m').textContent=MONTHS[now.getMonth()].toUpperCase();
  root.querySelector('.bgle-month .y').textContent=now.getFullYear();
  var first=(frappe.boot.user_info && frappe.boot.user_info[frappe.session.user] ?
    (frappe.boot.user_info[frappe.session.user].fullname||'').split(' ')[0] : '');
  var h=now.getHours(), part=h<12?'Good morning':(h<17?'Good afternoon':'Good evening');
  var days=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  var IC_SUN='<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="#f0a04b" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="12" r="4"/><path d="M12 2.5v2.4m0 14.2v2.4M4.9 4.9l1.7 1.7m10.8 10.8l1.7 1.7M2.5 12h2.4m14.2 0h2.4M4.9 19.1l1.7-1.7m10.8-10.8l1.7-1.7"/></svg>';
  var IC_DUSK='<svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="#f0a04b" stroke-width="2" stroke-linecap="round"><path d="M17 18a5 5 0 0 0-10 0"/><path d="M12 9V2m-7.3 8.7 1.4 1.4m13.8-1.4-1.4 1.4M1 18h2m18 0h2M3 22h18"/></svg>';
  var IC_MOON='<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#f0a04b" stroke-width="2" stroke-linecap="round"><path d="M21 12.8A9 9 0 1 1 11.2 3a7 7 0 0 0 9.8 9.8z"/></svg>';
  var IC=(h<12?IC_SUN:(h<17?IC_DUSK:IC_MOON));

  root.querySelector('.bgle-greet').innerHTML=IC+' '+days[now.getDay()]+' '+now.getDate()+' '+MONTHS[now.getMonth()]+' '+now.getFullYear();
  root.querySelector('.bgle-h1').innerHTML=part+(first?', '+first:'')+' - <b>here is Betonsa at a glance.</b>';

  // constellation: fixed corner block, palette follows theme
  var cv=root.querySelector('.bgle-sky'), cx=cv.getContext('2d'), pts=[];
  var W=340, H=170;
  cv.width=W; cv.height=H;
  cv.style.width=W+'px'; cv.style.height=H+'px';
  function dark(){
    var t=document.documentElement.getAttribute('data-theme');
    if(t) return t==='dark';
    return window.matchMedia && matchMedia('(prefers-color-scheme: dark)').matches;
  }
  var CD=['240,160,75','63,193,203','154,150,232'], CL=['194,97,12','13,111,119','91,83,168'];
  var lastTheme=null;
  function setup(){
    pts=[];
    var C=dark()?CD:CL;
    for(var i=0;i<14;i++) pts.push({x:Math.random()*W,y:Math.random()*H,
      vx:(Math.random()-.5)*.25,vy:(Math.random()-.5)*.25,c:C[i%3],r:Math.random()*1.6+.6,
      ph:Math.random()*6.283,tw:.8+Math.random()*1.8});
  }
  (function tick(){
    var t=dark();
    if(t!==lastTheme){ lastTheme=t; setup(); }
    cx.clearRect(0,0,W,H);
    pts.forEach(function(p){
      p.x+=p.vx; p.y+=p.vy;
      if(p.x<0||p.x>W)p.vx*=-1; if(p.y<0||p.y>H)p.vy*=-1;
      var tk=.2+.8*(.5+.5*Math.sin(performance.now()/1000*p.tw+p.ph));
      cx.beginPath(); cx.arc(p.x,p.y,p.r*(0.75+0.45*tk),0,6.283);
      cx.fillStyle='rgba('+p.c+','+(0.9*tk).toFixed(3)+')'; cx.fill();
    });
    for(var i=0;i<pts.length;i++)for(var j=i+1;j<pts.length;j++){
      var a=pts[i],b=pts[j],d=Math.hypot(a.x-b.x,a.y-b.y);
      if(d<110){ cx.beginPath(); cx.moveTo(a.x,a.y); cx.lineTo(b.x,b.y);
        cx.strokeStyle='rgba('+a.c+','+((t?0.18:0.24)*(1-d/110)).toFixed(3)+')'; cx.lineWidth=1; cx.stroke(); }
    }
    requestAnimationFrame(tick);
  })();

  frappe.call({method:'bgl_ops.api.dashboard_data'}).then(function(r){
    var d=r.message||{};
    var yq=0, ya=0;
    (d.yesterday_by_site||[]).forEach(function(y){ yq+=(+y.qty||0); ya+=(+y.amt||0); });
    root.querySelector('#bgle-yday').textContent=yq? (yq+' qty / GHS '+Math.round(ya).toLocaleString()) : 'no logs';
    var cost=(+((d.trips_month||{}).amt)||0)+(+((d.cubic_month||{}).amt)||0);
    root.querySelector('#bgle-cost').textContent=Math.round(cost).toLocaleString();
  });

  frappe.call({method:'bgl_ops.api.payroll_readiness', args:{month:ym}}).then(function(r){
    var d=r.message||{}, L={};
    (d.lines||[]).forEach(function(l){ L[l.key]=l; });
    root.querySelector('.bgle-ver').textContent='v'+(d.app_version||'');
    root.querySelector('#bgle-ready').textContent=d.ready?'READY':'IN PROGRESS';
    root.querySelector('#bgle-ready').style.color=d.ready?'#2fb56f':'#f0a04b';
    function agg(keys){
      var ok=true, det=[];
      keys.forEach(function(k){ var l=L[k]; if(!l) return;
        if(!l.ok) ok=false;
        if(!l.ok) det.push(l.detail); });
      return {ok:ok, det:det.join(' | ')};
    }
    var stones=[
      {l:'Trips & Cubic', t:'Trip sheets', a:agg(['sheet_airport','sheet_tema']), d:'Airport + Tema entered and locked'},
      {l:'Trips & Cubic', t:'Trip earnings', a:agg(['earnings']), d:'Generated from the locked sheets'},
      {l:'Payroll Numbers', t:'Payroll Prep Sheet', a:agg(['hires','doj','deductions','allowances','basics']), d:'Hires, loans, advances, absences, allowances'},
      {l:'Payroll Numbers', t:'Review drafts', a:agg(['foreign','review']), d:'Every draft approved; leavers flagged'},
      {l:'Payroll Numbers', t:'Payroll Entry', a:{ok:!!d.ready, det:''}, d:'Runs when all stones are green'}
    ];
    var rail=root.querySelector('.bgle-rail');
    var lineEl=document.createElement('div');
    lineEl.className='bgle-line';
    lineEl.innerHTML='<span class="spark"></span>';
    rail.appendChild(lineEl);
    var doneCount=0, nowSet=false;
    stones.forEach(function(st,i){
      var cls;
      if(st.a.ok){ cls='done'; doneCount++; }
      else if(!nowSet){ cls='now'; nowSet=true; }
      else cls='wait';
      var el=document.createElement('div');
      el.className='bgle-stg '+cls;
      el.innerHTML='<span class="st">'+(cls==='done'?'DONE':(cls==='now'?'OPEN':'WAITING'))+'</span>'+
        '<span class="n">'+(cls==='done'?'&#10003;':(i+1))+'</span>'+
        '<span style="display:block;font-size:9px;letter-spacing:.14em;text-transform:uppercase;opacity:.55;margin:2px 0 1px">'+(st.l||'')+'</span>'+'<b>'+st.t+'</b><span>'+((cls!=='done'&&st.a.det)?st.a.det:st.d)+'</span>';
      rail.appendChild(el);
    });
    var p1=(doneCount/5)*100, p2=(Math.min(doneCount+1,5)/5)*100;
    lineEl.style.background='linear-gradient(90deg,#2fb56f 0 '+p1+'%,#f0a04b '+p1+'% '+p2+'%,var(--border-color) '+p2+'%)';
  });

  // ---- Employee Hub ----
  (function(){
    var box=root.querySelector('.bgle-hub-search input');
    var drop=root.querySelector('.bgle-hub-drop');
    var card=root.querySelector('.bgle-hub-card');
    if(!box) return;
    // desk workspaces treat any keypress as global search - keep ours to ourselves
    ['keydown','keypress','keyup'].forEach(function(ev){
      box.addEventListener(ev, function(e){ e.stopPropagation(); });
    });
    var tmr=null;
    box.addEventListener('input', function(){
      clearTimeout(tmr);
      var q=box.value;
      if(q.trim().length<2){ drop.style.display='none'; return; }
      tmr=setTimeout(function(){
        frappe.call({method:'bgl_ops.api.employee_search', args:{q:q}}).then(function(r){
          var rows=r.message||[];
          if(!rows.length){ drop.style.display='none'; return; }
          drop.innerHTML=rows.map(function(e){
            return '<div data-e="'+e.name+'">'+e.employee_name+'<small>'+(e.designation||'')+' - '+(e.branch||'')+
              (e.status!=='Active'?' - '+e.status:'')+'</small></div>';
          }).join('');
          drop.style.display='block';
          drop.querySelectorAll('div').forEach(function(d){
            d.addEventListener('click', function(){ drop.style.display='none'; box.value=''; show(d.dataset.e); });
          });
        });
      }, 250);
    });
    document.addEventListener('click', function(ev){ if(!drop.contains(ev.target)&&ev.target!==box) drop.style.display='none'; });
    function fmt(v){ return (Math.round((+v||0)*100)/100).toLocaleString('en-GH',{minimumFractionDigits:2}); }
    function show(emp){
      frappe.call({method:'bgl_ops.api.employee_card', args:{employee:emp}}).then(function(r){
        var d=r.message||{}, e=d.emp||{};
        var ini=(e.employee_name||'?').split(' ').map(function(w){return w[0]||'';}).slice(0,2).join('').toUpperCase();
        var av=e.image? '<span class="av" style="background-image:url(\''+e.image+'\')"></span>'
                      : '<span class="av">'+ini+'</span>';
        var facts=[
          ['Branch', e.branch||'-'],['Designation', e.designation||'-'],
          ['Joined', e.date_of_joining? frappe.datetime.str_to_user(e.date_of_joining):'-'],
          ['Mobile', e.cell_number||'-'],
          ['Basic (GHS)', d.base? fmt(d.base):'-'],
          ['Loan balance', d.loan_balance? 'GHS '+fmt(d.loan_balance):'none'],
          ['Leave taken (yr)', (d.leave_taken||0)+' d'],
          ['Leave encashed', (d.leave_encashed||0)+' d'],
          ['Trips/cubic (mo)', (+((d.trips_month||{}).qty)||0)+' qty / GHS '+fmt((d.trips_month||{}).amt)]
        ];
        if(e.custom_truck_no) facts.splice(4,0,['Vehicle', e.custom_truck_no]);
        var acts='<a class="pri" href="/app/employee/EMP">Open record</a><a href="/app/salary-slip?employee=EMP">Salary slips</a><a href="/app/daily-trip-log?employee=EMP">Trip logs</a>'
          .replace(/EMP/g, encodeURIComponent(e.name));
        card.innerHTML='<div class="bgle-hc">'+av+
          '<div class="who"><b>'+e.employee_name+'</b><span>'+e.name+' - '+(e.status||'')+'</span></div>'+
          '<div class="facts">'+facts.map(function(f){
            return '<div class="f"><div class="l">'+f[0]+'</div><div class="v">'+f[1]+'</div></div>';
          }).join('')+'</div>'+
          '<div class="acts">'+acts+'</div></div>';
      });
    }
  })();

  // ---- Employee Hub hide/show (remembered per browser) ----
  (function(){
    var t=root.querySelector('.bgle-hub-t'), bd=root.querySelector('.bgle-hub-body');
    if(!t||!bd) return;
    var K='bglHubHidden', hid=false;
    try{ hid=localStorage.getItem(K)==='1'; }catch(e){}
    function ap(){ bd.style.display=hid?'none':'';
      var c=t.querySelector('.bgl-hub-chev'); if(c) c.innerHTML=hid?'&#9656;':'&#9662;'; }
    ap();
    t.addEventListener('click', function(ev){ ev.preventDefault(); ev.stopPropagation();
      hid=!hid;
      try{ localStorage.setItem(K, hid?'1':'0'); }catch(e){}
      ap(); });
  })();

})(typeof root_element !== 'undefined' ? root_element : null);
